import data.glitch_lib

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check in atomic units for attributes with unencrypted protocols
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check attribute values for cleartext URLs or insecure settings
    contains_insecure_protocol(attr.value)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext Transmission of Sensitive Information - Unencrypted protocols (HTTP, FTP) or insecure settings detected in configuration. (CWE-319)"
    }
}

Glitch_Analysis[result] {
